css:
/* A5 receipt. The PDF button still obeys Print Settings > PDF Page Size, so set that
   to A5 (or switch the PDF generator to chrome) for an exact A5 file. */
@page { size: A5 portrait; margin: 8mm; }
.eims-receipt { direction: rtl; text-align: right; font-family: Tahoma, Arial, sans-serif; font-size: 11px; color: #000; max-width: 132mm; margin: 0 auto; }
.eims-receipt .head { position: relative; text-align: center; margin-bottom: 8px; }
.eims-receipt .serial { position: absolute; left: 0; top: 2px; font-size: 12px; font-weight: bold; }
.eims-receipt .school { font-size: 16px; font-weight: bold; }
.eims-receipt .title { font-size: 15px; font-weight: bold; margin-top: 2px; }
.eims-receipt table { border-collapse: collapse; margin-bottom: 5px; }
.eims-receipt .method { margin-right: auto; margin-left: 0; }
.eims-receipt .method td { min-width: 70px; text-align: center; }
.eims-receipt .grid { width: 100%; }
.eims-receipt th, .eims-receipt td { border: 1px solid #000; padding: 3px 6px; text-align: right; }
.eims-receipt th { background: #eee; font-weight: bold; white-space: nowrap; }
.eims-receipt .grid td { width: 30%; }
.eims-receipt .wide th { width: 26%; }
.eims-receipt .wide td { width: auto; }
.eims-receipt .num { direction: ltr; text-align: right; }
.eims-receipt .note { margin: 8px 2px; line-height: 1.9; }
.eims-receipt .sign { width: 100%; margin-top: 22px; }
.eims-receipt .sign td { border: 0; padding: 0; }
.eims-receipt .sign .left { text-align: left; }
.eims-receipt .foot { border-top: 1px solid #000; margin-top: 14px; padding-top: 4px; text-align: center; font-size: 10px; }
